#include "can_v_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Mem_Generic * mem_request (void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

static SInt32 count_mem_in_use = 0 ;
static UInt32 count_mem_allocs = 0 ;

static Mem_Generic * mem_pool = NULL ;

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

ID_Set * can_v_mem_request_id_set (void)
{
  return (ID_Set   *) mem_request () ;
}

//--------------------------------------------------------------------------//

ID_Range * can_v_mem_request_id_range (void)
{
  return (ID_Range *) mem_request () ;
}

//--------------------------------------------------------------------------//

Lut_Map * can_v_mem_request_lut_map (void)
{
  return (Lut_Map *) mem_request () ;
}

//--------------------------------------------------------------------------//

void can_v_mem_release (void * mem)
{
  #define MEM ((Mem_Generic *) mem)

  MEM->next = mem_pool ;
  mem_pool  = MEM      ;

  #undef  MEM

  count_mem_in_use -- ;
}

//--------------------------------------------------------------------------//

static Mem_Generic * mem_request (void)
{
  count_mem_in_use ++ ;

  if (! mem_pool)
    {
      count_mem_allocs ++ ;

      return (Mem_Generic *) os_mem_request (sizeof (union s_Mem_Generic)) ;
    }
  else
    {
      Mem_Generic * mem = mem_pool ;

      mem_pool = mem_pool ->next   ;

      return mem ;
    }
}

